fn ima_bswap32(v: u32) -> u32 {
    ((v << 24) & 0xff000000) | ((v << 8) & 0x00ff0000) |
    ((v >> 8) & 0x0000ff00) | ((v >> 24) & 0x000000ff)
}

fn ima_bswap64(v: u64) -> u64 {
